parameters.functionCode:
// Build the artifact payload for GuardGate evaluation.
// Includes the target URL, method, and body so the rubric
// can assess risk based on what we are about to send.
const item = $input.first();
const d = item.json;
return [{
  json: {
    _request: {
      url: d.url || '',
      method: (d.method || 'GET').toUpperCase(),
      headers: d.headers || {},
      body: d.body || null
    },
    _config: {
      rubricPack: d.rubricPack || 'nomotic-core',
      blockTier: d.blockTier != null ? d.blockTier : 2,
      policyRef: d.policyRef || 'guarded-http-request-v1',
      approverId: d.approverId || 'system:guarded-http'
    }
  }
}];

// Merge the HTTP response back with guard metadata
// so EvidenceSeal has the full picture.
const item = $input.first();
const guard = item.json._guard || {};
const config = item.json._config || {};
const request = item.json._request || {};

// The HTTP Request node replaces $json with response data.
// We reconstruct a unified object.
return [{
  json: {
    _request: request,
    _response: {
      statusCode: item.json.statusCode || item.json.status || 200,
      body: item.json.body || item.json.data || item.json,
      received_at: new Date().toISOString()
    },
    _guard: guard,
    _config: config
  }
}];

// Build a blocked response so the caller knows why.
const item = $input.first();
const guard = item.json._guard || {};
return [{
  json: {
    blocked: true,
    risk_tier: guard.risk_tier,
    violations: guard.violations || [],
    evidence_hash: guard.evidence_hash || '',
    bead_id: guard.bead_id || null,
    message: 'Request blocked by GuardGate: risk tier ' + (guard.risk_tier || 'unknown') + ' exceeds threshold'
  }
}];
